<script setup lang="ts">
import { ref } from 'vue';
import { studio, edit } from '../stores/project-store';
import { uploadAsset } from '../services/local-api';
const error=ref(''), busy=ref(false);
async function restore(event: Event, sha: string){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;busy.value=true;error.value='';try{const asset=studio.document!.assets.find(a=>a.sha256===sha)!;const result=await uploadAsset(file,asset.mediaType);if(result.sha256!==sha)throw new Error('This file does not match the original SHA-256. Choose the exact original bytes; the saved project was not changed.');error.value='Original asset restored.';}catch(e){error.value=String(e);}finally{busy.value=false;}}
function permission(id: string,key: string,value: unknown){try{edit(p=>{const a=p.assets.find(a=>a.id===id)!;a.permission??={localUse:false,publication:false,redistribution:false,license:'Unresolved',credit:a.path};(a.permission as unknown as Record<string,unknown>)[key]=value;});}catch(e){error.value=String(e);}}
</script>
<template><q-card class="dialog-card"><q-card-section><div class="eyebrow">Project resources</div><h2>Keep the originals available</h2><p>Restore omitted files by their exact content hash. Permission changes are assertions by you; record the applicable terms and credit before enabling reuse.</p></q-card-section><q-card-section class="section-stack"><div v-for="asset in studio.document!.assets" :key="asset.id" class="mini-card"><b>{{ asset.path }}</b><p class="source-id">{{ asset.sha256 }}</p><div class="form-grid"><q-input :model-value="asset.permission?.license" outlined dense label="License / terms evidence" @change="e=>permission(asset.id,'license',e.target.value)" /><q-input :model-value="asset.permission?.credit" outlined dense label="Required credit" @change="e=>permission(asset.id,'credit',e.target.value)" /></div><div class="button-row"><q-checkbox v-for="entry in [{key:'localUse',label:'Local use'},{key:'publication',label:'Video publication'},{key:'redistribution',label:'Package redistribution'}]" :key="entry.key" :model-value="asset.permission?.[entry.key]??false" :label="entry.label" @update:model-value="v=>permission(asset.id,entry.key,v)" /></div><label>Restore original file<input :disabled="busy" type="file" @change="e=>restore(e,asset.sha256)" /></label></div><p v-if="error" role="status">{{ error }}</p></q-card-section><q-card-actions align="right"><q-btn flat label="Close" v-close-popup /></q-card-actions></q-card></template>
